import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"晉","description":"东坡易传 - 晉","frontmatter":{"title":"晉","description":"东坡易传 - 晉"},"headers":[],"relativePath":"zh/classics/dongpo/036.md","filePath":"zh/classics/dongpo/036.md"}'),o={name:"zh/classics/dongpo/036.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="晉" tabindex="-1">晉 <a class="header-anchor" href="#晉" aria-label="Permalink to “晉”">​</a></h1><p>“晉”：康侯，用錫馬，蕃庶，晝日三接。</p><p>《彖》曰：“晉”，進也。明出地上，順而麗乎大明，柔進而上行。是以“康侯，用錫馬，蕃庶，晝日三接”也。</p><p>“晉”以“離”爲君，“坤”爲臣。“坤”之爲物廣大博厚，非特臣爾，乃諸侯也。故曰“康侯”，君以是安諸侯也。夫“坤”順而“離”明，以順而進，趨於明，無有逆而不受者，故曰“錫馬”。馬所以進也，錫之馬而使蕃之，許其進之甚也。一日三接，喜其來之至也。</p><p>象曰：明出地上，“晉”，君子以自昭明德。</p><p>初六：晉如，摧如，貞吉。罔孚，裕，無咎。象曰：“晉如摧如”，獨行正也；“裕無咎”，未受命也。</p><p>三陰皆進而之“離”，九四居於其衝，欲並而有之，衆之所不與也。初六有應於四，將以衆適四，故進而衆摧之也。夫初六之適四，正也；其以衆適四，不正也。已獨行而不以衆，則得其正矣，故曰“貞吉”。我雖正矣，而衆莫吾信，故“裕”之而後“無咎”。裕之而後無咎者，衆未肯受吾命也。</p><p>六二：晉如，愁如，貞吉。受茲介福，於其王母。象曰：“受茲介福”，以中正也。</p><p>將進而之五，而四欲得之，故“晉如，愁如”。我守吾正，雖四爲拒，不能終閉也，故受福於王母。六五之謂王母也，以其爲王母，故二雖陰，亦可得而歸之矣。</p><p>六三：無允，悔亡。象曰：“無允”之，志上行也。</p><p>將適上九而近於四，悔也。雖與之近，而衆信其不與也，故“悔亡”。</p><p>九四：晉如，鼫鼠，貞厲。象曰：“鼫鼠貞厲”，位不當也。</p><p>求得而未必能者，鼫鼠也。六二、六三，非其所當得也。因其過我欲兼有之，而衆不聽，故曰“晉如，鼫鼠”。九四之有初六，正也；非其正者，固不可得矣。而正者猶危，則位不當之故也。</p><p>六五：悔亡。失得勿恤，往吉，無不利。象曰：“失得勿恤”，往有慶也。</p><p>四奪其與，悔也。然而衆不與四，是以“悔亡”。夫以五之尊而下與四爭，其所附則陋矣，故雖失所當得，“勿恤”，而往則吉。夫下與四爭，必來；來者爭也，則往者不爭之至也。五猶不爭，而四何敢不置之？故其所失，終亦必得而已矣。苟終於得，則其不爭，非獨四之利也。</p><p>上九：晉其角，維用伐邑，厲吉無咎，貞吝。象曰：“維用伐邑”，道未光也。</p><p>剛之上窮者，角也。“晉其角”者，以是爲晉也。以角爲晉，必有所用其觸。三，吾應也①；而四閉之，則上九之所伐者，四也。四與上同體，故爲邑也。邑人而閉吾應，無以令之而至於用兵，道不光矣。此正也，而吝道也。故知戒於危，然後其吉，可以無咎。</p><p>【校注】 ① 吾應也：《蘇氏易傳》作“五應也”，誤。</p>',18)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
